command:
const MODULE_ID = "substances-and-paraphernalia";
const FLAG_SOURCE = "sourceSubstanceId";
const FLAG_WITHDRAWAL = "withdrawal";
if (!game.user.isGM) { ui.notifications.warn("GM only."); return; }
const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) { ui.notifications.warn(game.i18n.localize("FISHUT.RemoveAddiction.NoActor")); return; }
const record = actor.getFlag(MODULE_ID, FLAG_WITHDRAWAL) ?? {};
const orphanIds = new Set(Object.keys(record));
const rows = [];
for (const effect of actor.effects) {
  const sid = effect.flags?.[MODULE_ID]?.[FLAG_SOURCE] ?? null;
  const aeRole = effect.flags?.[MODULE_ID]?.aeRole ?? null;
  const legacy = aeRole == null && /withdraw/i.test(effect.name ?? "");
  if (aeRole !== "withdrawal" && !legacy) continue;
  if (legacy) console.warn(`[${MODULE_ID}] Remove Withdrawal: matched legacy AE "${effect.name}" by name substring (no aeRole flag).`);
  rows.push({ effect, sourceId: sid });
  if (sid) orphanIds.delete(sid);
}
for (const sid of orphanIds) rows.push({ effect: null, sourceId: sid });
if (rows.length === 0) { ui.notifications.info(game.i18n.format("FISHUT.RemoveWithdrawal.NoCandidates", { actor: actor.name })); return; }
const body = `${game.i18n.format("FISHUT.RemoveWithdrawal.PreviewIntro", { actor: actor.name })}<ul style="list-style:none;padding-left:0;">${rows.map((r, i) => `<li><label><input type="checkbox" name="row-${i}" checked> ${game.i18n.format("FISHUT.RemoveWithdrawal.RowDetail", { name: r.effect?.name ?? "(orphan flag)", sourceId: r.sourceId ?? "(none)" })}</label></li>`).join("")}</ul>`;
const result = await foundry.applications.api.DialogV2.wait({
  window: { title: game.i18n.localize("FISHUT.RemoveWithdrawal.Title") },
  content: body,
  buttons: [
    { action: "confirm", label: game.i18n.localize("FISHUT.RemoveAddiction.Confirm"), default: true,
      callback: (event, button) => { const fd = new FormData(button.form); return rows.map((_, i) => fd.has(`row-${i}`)); } },
    { action: "cancel", label: game.i18n.localize("FISHUT.RemoveAddiction.Cancel"), default: false,
      callback: () => null }
  ],
  rejectClose: false, modal: true,
});
if (!Array.isArray(result)) return;
const chosen = rows.filter((_, i) => result[i]);
if (chosen.length === 0) return;
// Deleting a withdrawal effect ends the addiction as well: the module's
// cleanup hook clears the record and removes the Addiction effect. Record
// entries with no effect are cleared here.
const withEffect = chosen.filter((r) => r.effect);
if (withEffect.length) await actor.deleteEmbeddedDocuments("ActiveEffect", withEffect.map((r) => r.effect.id), { fishutIntentional: true });
const clears = {};
for (const r of chosen) if (!r.effect && r.sourceId) clears[`flags.${MODULE_ID}.${FLAG_WITHDRAWAL}.${r.sourceId}`] = new foundry.data.operators.ForcedDeletion();
if (Object.keys(clears).length) await actor.update(clears);
if (withEffect.length) {
  await ChatMessage.create({
    user: game.user.id,
    whisper: ChatMessage.getWhisperRecipients("GM").map((u) => u.id),
    content: `<details><summary>${game.i18n.localize("FISHUT.RemoveWithdrawal.LogTitle")}</summary><pre>${foundry.utils.escapeHTML(JSON.stringify(withEffect.map((r) => r.effect.toObject()), null, 2))}</pre></details>`,
  });
}
ui.notifications.info(game.i18n.format("FISHUT.RemoveWithdrawal.Removed", { actor: actor.name, count: chosen.length }));
